import React from 'react';
import { questions } from '../data/questions';

const Summary = ({ answers, onRestart }) => {
  // Calculate total cost
  const totalCost = Object.values(answers).reduce((sum, answer) => sum + (answer?.cost || 0), 0);

  // Get funeral details
  const getFuneralDetails = () => {
    const belief = answers[1]?.text || 'ไม่ระบุ';
    const style = answers[2]?.text || 'ไม่ระบุ';
    const legacy = answers[3]?.text || 'ไม่ระบุ';
    const ritual = answers[4]?.text || 'ไม่ระบุ';
    const activity = answers[5]?.text || 'ไม่ระบุ';
    const food = answers[6]?.text || 'ไม่ระบุ';
    const flower = answers[7]?.text || 'ไม่ระบุ';
    const souvenir = answers[8]?.text || 'ไม่ระบุ';
    const music = answers[9]?.text || 'ไม่ระบุ';
    const venue = answers[10]?.text || 'ไม่ระบุ';
    const ceremony = answers[11]?.text || 'ไม่ระบุ';
    const snack = answers[12]?.text || 'ไม่ระบุ';

    return {
      belief,
      style,
      legacy,
      ritual,
      activity,
      food,
      flower,
      souvenir,
      music,
      venue,
      ceremony,
      snack
    };
  };

  const details = getFuneralDetails();

  // Calculate break-even points
  const breakEvenPoints = {
    '500': Math.ceil(totalCost / 500),
    '1000': Math.ceil(totalCost / 1000),
    '2000': Math.ceil(totalCost / 2000)
  };

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: 'แผนงานศพของฉัน',
        text: `สไตล์: ${details.style}\nงบประมาณ: ${totalCost.toLocaleString()} บาท\nจุดคุ้มทุน: ${breakEvenPoints['500']} คน (500 บาท/คน)`,
        url: window.location.href
      });
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-900 to-black text-white p-6 animate-fade-in">
      <div className="max-w-4xl mx-auto space-y-8">
        {/* Header */}
        <div className="text-center space-y-4 animate-slide-up">
          <div className="relative">
            <h1 className="text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-red-500 to-pink-500">
              📋 สรุปแผนงานศพของคุณ
            </h1>
            <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 w-32 h-1 bg-gradient-to-r from-red-500 to-pink-500 rounded-full"></div>
          </div>
          <p className="text-2xl text-gray-300 mt-4">💎 สไตล์: {details.style}</p>
        </div>

        {/* Funeral Details */}
        <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 shadow-xl animate-slide-up" style={{ animationDelay: '0.2s' }}>
          <h2 className="text-3xl font-bold text-red-400 mb-6">รายละเอียดงานศพ</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div>
                <h3 className="text-lg font-semibold text-gray-300">🏨 สถานที่</h3>
                <p className="text-white">{details.venue}</p>
              </div>
              <div>
                <h3 className="text-lg font-semibold text-gray-300">🕰️ ระยะเวลา</h3>
                <p className="text-white">{details.style}</p>
              </div>
              <div>
                <h3 className="text-lg font-semibold text-gray-300">🎵 ดนตรี</h3>
                <p className="text-white">{details.music}</p>
              </div>
              <div>
                <h3 className="text-lg font-semibold text-gray-300">🎁 ของที่ระลึก</h3>
                <p className="text-white">{details.souvenir}</p>
              </div>
            </div>
            <div className="space-y-4">
              <div>
                <h3 className="text-lg font-semibold text-gray-300">🎭 กิจกรรม</h3>
                <p className="text-white">{details.activity}</p>
              </div>
              <div>
                <h3 className="text-lg font-semibold text-gray-300">🕊️ บรรยากาศ</h3>
                <p className="text-white">{details.legacy}</p>
              </div>
              <div>
                <h3 className="text-lg font-semibold text-gray-300">🙏 พิธีกรรม</h3>
                <p className="text-white">{details.ceremony}</p>
              </div>
              <div>
                <h3 className="text-lg font-semibold text-gray-300">💬 ความทรงจำที่คุณฝากไว้</h3>
                <p className="text-white">{details.legacy}</p>
              </div>
            </div>
          </div>
        </div>

        {/* Cost Analysis */}
        <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 shadow-xl animate-slide-up" style={{ animationDelay: '0.4s' }}>
          <h2 className="text-3xl font-bold text-red-400 mb-6">💰 งบประมาณและจุดคุ้มทุน</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="text-center p-6 bg-gray-700/50 rounded-xl">
              <h3 className="text-xl font-semibold text-gray-300 mb-2">งบโดยรวม</h3>
              <p className="text-4xl font-bold text-white">{totalCost.toLocaleString()} บาท</p>
            </div>
            <div className="text-center p-6 bg-gray-700/50 rounded-xl">
              <h3 className="text-xl font-semibold text-gray-300 mb-2">จุดคุ้มทุน</h3>
              <div className="space-y-2">
                <p className="text-lg text-white">{breakEvenPoints['500']} คน (500 บาท/คน)</p>
                <p className="text-lg text-white">{breakEvenPoints['1000']} คน (1,000 บาท/คน)</p>
                <p className="text-lg text-white">{breakEvenPoints['2000']} คน (2,000 บาท/คน)</p>
              </div>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex justify-center space-x-4 animate-fade-in-delay">
          <button
            onClick={onRestart}
            className="px-8 py-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors duration-300"
          >
            เริ่มต้นใหม่
          </button>
          <button
            onClick={handleShare}
            className="px-8 py-3 bg-gray-700 text-white rounded-xl hover:bg-gray-600 transition-colors duration-300"
          >
            แชร์ผลลัพธ์
          </button>
        </div>

        {/* Footer with Quote */}
        <div className="text-center space-y-4 animate-fade-in-delay">
          <div className="relative">
            <p className="text-2xl italic text-gray-300">
              "งานศพของคุณจะเป็นงานที่สวยงาม หรูหรา และเต็มไปด้วยความรักและความทรงจำดี ๆ"
            </p>
            <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 w-16 h-0.5 bg-red-500 rounded-full"></div>
          </div>
          <p className="text-sm text-gray-500">#วางแผนงานศพ #เตรียมตัวก่อนตาย</p>
        </div>
      </div>
    </div>
  );
};

export default Summary;
